WITH unpacked AS (SELECT id, plan, effective_from, currency, tier_limits, tier_prices, discounts, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT *, NTILE(4) OVER (PARTITION BY currency ORDER BY avg_tier_price, id) AS avg_tier_price_bucket, SUM(lowest_price) OVER (ORDER BY lowest_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_lowest_price, SUM(avg_tier_price) OVER (PARTITION BY plan) AS plan_sum_avg_tier_price FROM unpacked WHERE currency != 'EUR';
